def _opt(n, edges, target=None):
    target = tuple(target or [0] * n)
    states = {(0,) * n: 0}
    for u, v, low, high, cost in edges:
        nxt = {}
        for balance, value in states.items():
            for flow in range(low, high + 1):
                b = list(balance)
                b[u] += flow
                b[v] -= flow
                key = tuple(b)
                val = value + flow * cost
                if key not in nxt or val < nxt[key]:
                    nxt[key] = val
        states = nxt
    return states.get(target)

def versioned_circulation_costs(data):
    snapshots = [[list(e) for e in data['arcs']]]
    answers = [_opt(data['n'], snapshots[0])]
    for parent, index, low, high, cost in data['versions']:
        edges = [e[:] for e in snapshots[parent]]
        edges[index][2:] = [low, high, cost]
        snapshots.append(edges)
        answers.append(_opt(data['n'], edges))
    return answers

def _chart(data, counting=False):
    budget = data['budget']
    table = [[{} for _ in range(budget + 1)] for _ in range(data['n'])]
    for spent in range(1, budget + 1):
        for lhs, rhs, resource, cost in data['rules']:
            left = spent - resource
            if left < 0:
                continue
            possibilities = []
            if not rhs:
                if left == 0:
                    possibilities.append(('', 1 if counting else cost))
            elif type(rhs[0]) is str:
                if left == 0:
                    possibilities.append((rhs[0], 1 if counting else cost))
            elif len(rhs) == 1:
                for word, value in table[rhs[0]][left].items():
                    possibilities.append((word, value if counting else value + cost))
            else:
                for first in range(1, left):
                    for a, av in table[rhs[0]][first].items():
                        for b, bv in table[rhs[1]][left-first].items():
                            possibilities.append((a+b, av*bv if counting else av+bv+cost))
            dest = table[lhs][spent]
            for word, value in possibilities:
                if counting and word not in data['text']:
                    continue
                if counting:
                    dest[word] = (dest.get(word, 0) + value) % 1000000007
                elif word not in dest or value < dest[word]:
                    dest[word] = value
    return table[data['start']]

def budget_parse_cost(data):
    values = [row[data['text']] for row in _chart(data) if data['text'] in row]
    return min(values) if values else None

def _evaluate(e, env, store):
    if type(e) is int:
        return e
    op, *a = e
    if op == 'var':
        return env[a[0]]
    if op == 'let':
        value = _evaluate(a[1], env, store)
        return _evaluate(a[2], dict(env, **{a[0]: value}), store)
    if op == 'fn':
        return ('closure', a[0], a[1], env.copy())
    if op == 'call':
        f = _evaluate(a[0], env, store)
        x = _evaluate(a[1], env, store)
        return _evaluate(f[2], dict(f[3], **{f[1]: x}), store)
    if op == 'seq':
        _evaluate(a[0], env, store)
        return _evaluate(a[1], env, store)
    if op == 'if':
        return _evaluate(a[1] if _evaluate(a[0], env, store) != 0 else a[2], env, store)
    if op == 'snap':
        return ('snapshot', tuple(store))
    if op == 'restore':
        snapshot = _evaluate(a[0], env, store)
        store[:] = snapshot[1]
        return _evaluate(a[1], env, store)
    if op == 'ref':
        value = _evaluate(a[0], env, store)
        index = len(store)
        store.append(value)
        return ('cell', index)
    if op == 'get':
        return store[_evaluate(a[0], env, store)[1]]
    if op == 'set':
        cell = _evaluate(a[0], env, store)
        value = _evaluate(a[1], env, store)
        store[cell[1]] = value
        return value
    left = _evaluate(a[0], env, store)
    right = _evaluate(a[1], env, store)
    return left + right if op == 'add' else left - right

def _initial(bindings):
    env, store = {}, []
    for name, expression in bindings:
        env[name] = _evaluate(expression, env, store)
    return env, store

def store_program_result(arg):
    env, store = _initial(arg['bindings'])
    value = _evaluate(arg['program'], env, store)
    return {'value': value, 'store': store}

def forked_store_observations(arg):
    env, initial = _initial(arg['bindings'])
    stores, results = [], []
    for branch in arg['branches']:
        store = (initial if branch['from'] == -1 else stores[branch['from']]).copy()
        value = _evaluate(branch['program'], env, store)
        stores.append(store)
        results.append({'value': value, 'store': store.copy()})
    return results

def bounded_store_equivalence(arg):
    different = []
    for x in arg['domain']:
        observations = []
        for program in (arg['left'], arg['right']):
            store = []
            observations.append((_evaluate(program, {'x': x}, store), store))
        if observations[0] != observations[1]:
            different.append(x)
    return {'equivalent': not different, 'different_inputs': different}

def _route(arg, vehicle, indices):
    requests = arg['requests']
    best = None
    def visit(node, time, load, picked, done, cost):
        nonlocal best
        if len(done) == len(indices):
            if time + arg['time'][node][vehicle['end']] <= vehicle['deadline']:
                total = cost + arg['cost'][node][vehicle['end']]
                if best is None or total < best:
                    best = total
            return
        for i in indices:
            r = requests[i]
            if i in done:
                continue
            delivery = i in picked
            target = r['drop'] if delivery else r['pick']
            window = r['dw'] if delivery else r['pw']
            newload = load + (-r['load'] if delivery else r['load'])
            start = max(time + arg['time'][node][target], window[0])
            if newload > vehicle['capacity'] or start > window[1]:
                continue
            duration = r['ds'] if delivery else r['ps']
            visit(target, start + duration, newload, picked | {i},
                  done | {i} if delivery else done, cost + arg['cost'][node][target])
    visit(vehicle['start'], vehicle['release'], 0, set(), set(), 0)
    return best

def pickup_delivery_cost(arg):
    return _route(arg, arg['vehicle'], list(range(len(arg['requests']))))

def fleet_assignment_cost(arg):
    from itertools import product
    best = None
    vehicles = arg['vehicles']
    for assignment in product(range(len(vehicles)), repeat=len(arg['requests'])):
        total = 0
        for j, vehicle in enumerate(vehicles):
            cost = _route(arg, vehicle, [i for i, v in enumerate(assignment) if v == j])
            if cost is None:
                break
            total += cost
        else:
            if best is None or total < best:
                best = total
    return best

def reward_delivery_selection(arg):
    best = 0
    for mask in range(1 << len(arg['requests'])):
        indices = [i for i in range(len(arg['requests'])) if mask >> i & 1]
        cost = _route(arg, arg['vehicle'], indices)
        if cost is not None and cost <= arg['budget']:
            best = max(best, sum(arg['requests'][i]['reward'] for i in indices))
    return best

from functools import lru_cache

def automaton_route_cost(a):
    n = a['n']; budget = a['budget']; accept = set(a['accept'])
    outgoing = [[] for _ in range(n)]
    for u,v,label,r,c in a['edges']:
        outgoing[u].append((v,label,r,c))
    @lru_cache(None)
    def solve(v,q,left):
        values = [0] if v == a['goal'] and q in accept else []
        for w,label,r,c in outgoing[v]:
            if r <= left:
                sub = solve(w,a['delta'][q][label],left-r)
                if sub is not None: values.append(c+sub)
        return min(values,default=None)
    return solve(a['start'],a['state'],budget)

def constrained_edit_cost(a):
    # Each layer contains all prefixes of a fixed operation count.
    layer = {(0,0,a['state'],a['mode']):(0,1)}
    best = None; count = 0
    for step in range(a['max_ops']+1):
        following = {}
        for (i,length,q,m),(value,ways) in layer.items():
            if i == len(a['text']) and q in a['accept']:
                if best is None or value < best: best,count = value,ways
                elif value == best: count = (count+ways)%1000000007
            if step == a['max_ops']: continue
            for op in range(3):
                if op != 0 and i == len(a['text']): continue
                emissions = [None] if op == 1 else range(len(a['alphabet']))
                for c in emissions:
                    size = length+(c is not None)
                    if size > a['max_output']: continue
                    target = (i+(op!=0),size,q if c is None else a['delta'][q][c],a['next_mode'][m][op])
                    candidate = value+a['cost'][m][op]
                    old = following.get(target)
                    if old is None or candidate < old[0]: following[target] = (candidate,ways)
                    elif candidate == old[0]: following[target] = (candidate,(old[1]+ways)%1000000007)
        layer = following
    return best
